function failureMessage(failure: unknown) {
  if (
    typeof failure === "object" &&
    failure !== null &&
    "kind" in failure &&
    failure.kind === "timeout"
  ) {
    return "Timed out";
  }
  return "Cancelled";
}

codes.good:
type Failure = { kind: "timeout" } | { kind: "cancelled" };

function failureMessage(failure: Failure) {
  return failure.kind === "timeout" ? "Timed out" : "Cancelled";
}

